/**
 * Local search over Surfline's spot list.
 *
 * The data lives in src/data/surflineSpots.json (generated by
 * scripts/build-surfline-spots.js) and is loaded on demand as its own chunk
 * the first time a search runs. Used by the Add Spot form so a query like
 * "manhattan" returns Manhattan Beach Pier instead of Manhattan, NY.
 */

let indexPromise = null

/** Kick off loading the spot list; safe to call repeatedly. */
export function preloadSurflineSpots() {
  indexPromise ??= import('../data/surflineSpots.json')
    .then(m => buildIndex(m.default))
    .catch(err => {
      indexPromise = null // let a later search retry (e.g. after coming back online)
      throw err
    })
  return indexPromise
}

/** Lowercase, strip accents and punctuation, collapse whitespace. */
export function normalize(s) {
  return s
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/['’]/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim()
}

/**
 * Expand the compact JSON into searchable records:
 * { id, name, latitude, longitude, region: string[], displayName, source }
 */
export function buildIndex({ regions, spots }) {
  const pathCache = new Map()
  function pathFor(idx) {
    if (idx < 0) return []
    if (pathCache.has(idx)) return pathCache.get(idx)
    const [name, parent] = regions[idx]
    const path = [...pathFor(parent), name]
    pathCache.set(idx, path)
    return path
  }
  return spots.map(([id, name, latitude, longitude, regionIdx]) => {
    const region = pathFor(regionIdx)
    return {
      id,
      name,
      latitude,
      longitude,
      region,
      displayName: region.join(' › '),
      source: 'surfline',
      // Padded with spaces so " foo" tests for a match at the start of a word.
      nameKey: ` ${normalize(name)} `,
      regionKey: ` ${normalize(region.join(' '))} `,
    }
  })
}

function textScore(spot, q, tokens) {
  const { nameKey, regionKey } = spot
  if (nameKey.startsWith(` ${q}`)) return 90                            // name starts with the query (incl. exact)
  if (nameKey.includes(` ${q}`)) return 80                              // query starts a later word in the name
  if (tokens.every(t => nameKey.includes(` ${t}`))) return 70           // every word starts a word, any order
  if (nameKey.includes(q)) return 60                                    // substring of the name
  if (tokens.every(t => nameKey.includes(t) || regionKey.includes(` ${t}`))) return 40 // name + region together
  return 0
}

/** Approximate great-circle distance in km (equirectangular — plenty for ranking). */
function distanceKm(spot, near) {
  const dLat = spot.latitude - near.latitude
  const dLon = (spot.longitude - near.longitude) * Math.cos(((spot.latitude + near.latitude) / 2) * Math.PI / 180)
  return Math.sqrt(dLat * dLat + dLon * dLon) * 111
}

/** Small bounded bonus for spots near the user, so "sunset" favours Sunset Cliffs over a Sunset abroad. */
function proximityBonus(km) {
  if (km <= 150) return 15
  if (km <= 600) return 10
  if (km <= 2500) return 5
  return 0
}

/**
 * Rank spots for a query. `near` is typically the centre of the user's
 * existing spots; it nudges nearby matches up a tier and breaks ties, but
 * can't lift a weak text match above a strong one.
 */
export function rankSpots(index, query, { limit = 8, near = null } = {}) {
  const q = normalize(query)
  if (!q) return []
  const tokens = q.split(' ')
  const matches = []
  for (const spot of index) {
    const text = textScore(spot, q, tokens)
    if (text === 0) continue
    const km = near ? distanceKm(spot, near) : 0
    matches.push({ spot, score: text + (near ? proximityBonus(km) : 0), km })
  }
  matches.sort((a, b) =>
    b.score - a.score
    || a.km - b.km
    || a.spot.name.length - b.spot.name.length
    || a.spot.name.localeCompare(b.spot.name),
  )
  return matches.slice(0, limit).map(m => m.spot)
}

export async function searchSurflineSpots(query, options) {
  const index = await preloadSurflineSpots()
  return rankSpots(index, query, options)
}

/** Average position of the given points (anything with latitude/longitude), or null. */
export function centroid(points) {
  const located = points.filter(p => p.latitude != null && p.longitude != null)
  if (located.length === 0) return null
  return {
    latitude: located.reduce((sum, p) => sum + p.latitude, 0) / located.length,
    longitude: located.reduce((sum, p) => sum + p.longitude, 0) / located.length,
  }
}
